import {asciiSettings,renderAscii} from './ascii.js';
import {$,$$,safe,clamp,uid,download,slug,toast,filePicker,blobFromCanvas} from '../app/utils.js';
import {imagePresets,clonePreset,processEffect,EFFECT_LABELS} from './effects.js';
import {MASK_REGIONS,DEFAULT_MASK} from './masking.js';
const CATEGORIES=['ALL','BITMAP','DITHER','PRINT','COLOR','DISTORT','DIGITAL','SIGNAL','EXPERIMENTAL'];
const colorDefaults={hue:0,saturation:100,contrast:100,brightness:100,exposure:0,gamma:100};
const BLENDS=['source-over','multiply','screen','overlay','difference','lighten','darken','color-dodge'];
export class ImageLab{
 constructor(root,onUpdate,saved,onBridge){this.root=root;this.onUpdate=onUpdate;this.onBridge=onBridge;this.layers=[];this.sources=new Map();this.renderCache=new Map();this.selected=null;this.category='ALL';this.quality='BALANCED';this.color={...colorDefaults};this.sourceMeta=null;this.width=0;this.height=0;this.history=[];this.future=[];this.zoom=1;this._renderTimer=0;this._thumbToken=0;this.thumbCache=new Map();this.search='';this.relink=[];this.restore(saved);this.render();}
 restore(data){if(!data)return;this.category=data.category||'ALL';this.selected=data.selected||null;this.layers=data.layers||[];this.quality=data.quality||'BALANCED';this.color={...colorDefaults,...data.color};this.width=data.width||0;this.height=data.height||0;this.relink=data.assets||this.layers.map(l=>({name:l.sourceName||l.name,id:l.sourceId}));this.zoom=data.zoom||1;}
 serialize(){return {layers:this.layers,selected:this.selected,category:this.category,quality:this.quality,color:this.color,width:this.width,height:this.height,zoom:this.zoom,assets:this.layers.map(l=>({id:l.sourceId,name:this.sources.get(l.sourceId)?.name||l.sourceName||l.name}))};}
 snapshot(){this.history.push(JSON.stringify(this.serialize()));if(this.history.length>40)this.history.shift();this.future=[];}
 undo(){if(!this.history.length)return;this.future.push(JSON.stringify(this.serialize()));this.restore(JSON.parse(this.history.pop()));this.render();this.update()}
 redo(){if(!this.future.length)return;this.history.push(JSON.stringify(this.serialize()));this.restore(JSON.parse(this.future.pop()));this.render();this.update()}
 update(){this.onUpdate?.();}
 selectedLayer(){return this.layers.find(l=>l.id===this.selected)||this.layers.at(-1)}
 get source(){return this.sources.get(this.selectedLayer()?.sourceId)||[...this.sources.values()][0]||null}
 render(){this.root.innerHTML=`<div class="lab-layout image-workspace"><aside class="library-panel"><div class="section-heading"><span>PHOTO SYSTEMS</span><b>/${String(imagePresets.length).padStart(2,'0')}</b></div>
 <div class="filter-pills">${CATEGORIES.map(c=>`<button class="filter ${this.category===c?'active':''}" data-filter="${c}">${c}</button>`).join('')}</div>
 <button id="image-ascii" class="ascii-entry"><strong>ASCII / IMAGE TO TYPE ↗</strong><small>FIDELITY · EXPERIMENTAL</small></button><input id="preset-search" type="search" placeholder="Find a visual treatment…" aria-label="Search presets" value="${safe(this.search)}"><div class="preset-catalog">${imagePresets.filter(p=>(this.category==='ALL'||p.category===this.category)&&((p.name+' '+p.category).toLowerCase().includes(this.search.toLowerCase()))).map(p=>`<button class="preset-card" data-preset="${p.id}" title="Add ${safe(p.name)}"><span class="preset-preview" data-thumb="${p.id}"><span class="preset-index">${String(p.mode+1).padStart(2,'0')}</span></span><span class="preset-text"><strong>${safe(p.name)}</strong><small>${safe(p.category)}</small></span></button>`).join('')}</div>
 <div class="sidebar-note">PRESET PIPELINE <span>V.04 / CUSTOMIZABLE</span></div></aside>
 <main class="visual-stage"><div class="stage-toolbar"><div class="bar-label"><span class="status-dot"></span>IMAGE PROCESSOR <small>/ LOCAL OUTPUT</small></div><div class="stage-options"><button class="toolbtn" id="image-load">↥ LOAD SOURCE</button><button class="toolbtn primary" id="image-bridge" title="Send the processed image into Audio Lab">↗ MAKE REACTIVE</button><button class="toolbtn" id="image-compose" title="Send the processed image into Generative Lab">↗ COMPOSE</button><button class="toolbtn" id="zoom-out">−</button><span class="zoom-amount" id="zoom-label">${Math.round(this.zoom*100)}%</span><button class="toolbtn" id="zoom-in">+</button><button class="toolbtn" id="zoom-fit">FIT</button></div></div>
 <div class="visual-main image-main" id="image-drop"><div class="image-canvas-holder" style="transform:scale(${this.zoom})"><canvas id="image-canvas" width="900" height="590" aria-label="Image editing canvas"></canvas>${this.source?'':`<div class="canvas-empty"><span>✳ / IMAGE INPUT</span><strong>MAKE SOMETHING<br>UNEXPECTED.</strong><p>DROP AN IMAGE TO BEGIN</p><button class="toolbtn primary" id="image-empty-load">↥ SELECT SOURCE</button>${this.relink.length?`<p class="relink-hint">PROJECT RESTORED — RELOAD: ${safe(this.relink.map(x=>x.name).join(', '))}</p>`:''}</div>`}</div></div>
 <div class="stage-status"><span id="image-dimensions">${this.source?`${this.width} × ${this.height} PX`:'NO IMAGE SOURCE'}</span><span>PREVIEW: <select id="image-quality">${['PERFORMANCE','BALANCED','QUALITY'].map(x=>`<option ${this.quality===x?'selected':''}>${x}</option>`).join('')}</select></span><span id="render-status">READY / LOCAL</span></div></main>
 <aside class="inspector-panel"><div class="section-heading"><span>INSPECTOR</span><b>[ IMAGE ]</b></div><div class="inspector-content" id="image-inspector">${this.inspector()}</div></aside></div>`;
 this.bind();this.renderCanvas();this.buildThumbnails();}
 inspector(){const l=this.selectedLayer();return `<div class="inspector-lead"><span class="overline">COMPOSITION / IMAGE</span><h2>${l?safe(l.name):'NO LAYER'}</h2><p>${l?'Stack effects, adjust output and combine sources.':'Load media and select one of the systems to start.'}</p></div>
 ${l?`<div class="inspector-block"><div class="block-heading">SELECTED LAYER <span>${this.layers.indexOf(l)+1}/${this.layers.length}</span></div><div class="control"><div class="control-top"><label>OPACITY</label><output id="layer-opacity-value">${Math.round(l.opacity*100)}%</output></div><input type="range" data-layer-value="opacity" min="0" max="1" step=".01" value="${l.opacity}"></div><label class="input-label">BLEND MODE <select data-layer-value="blend">${BLENDS.map(v=>`<option value="${v}" ${l.blend===v?'selected':''}>${v.toUpperCase()}</option>`).join('')}</select></label></div>`:''}
 <div class="inspector-block"><div class="block-heading">EFFECT STACK <span>${l?.effects?.length||0}</span></div>${l?.effects?.length?l.effects.map((fx,i)=>`<div class="effect-system" data-effect="${fx.uid}" draggable="true"><div class="effect-header"><span class="drag-handle">⠿</span><button data-effect-action="toggle:${fx.uid}" title="Toggle effect" class="icon-button">${fx.enabled?'●':'○'}</button><strong>${safe(fx.name)}</strong><button data-effect-action="up:${fx.uid}" class="icon-button" title="Move up">↑</button><button data-effect-action="down:${fx.uid}" class="icon-button" title="Move down">↓</button><button data-effect-action="delete:${fx.uid}" class="icon-button" title="Delete">×</button></div>${['amount','scale','contrast',...(fx.mode!==15||fx.asciiMode==='experimental'?['distortion']:[])].map(key=>{const min=key==='scale'?1:key==='contrast'?.4:0,max=key==='scale'?20:key==='contrast'?3:1;return `<div class="control compact-control"><div class="control-top"><label>${EFFECT_LABELS[fx.mode]?.[key]||key.toUpperCase()}</label><output data-fx-value="${fx.uid}:${key}">${Number(fx[key]).toFixed(key==='scale'?0:2)}</output></div><input type="range" data-fx-range="${fx.uid}:${key}" min="${min}" max="${max}" step="${key==='scale'?1:.01}" value="${fx[key]}"></div>`}).join('')}${fx.mode===15?this.asciiControls(fx):''}<details class="effect-advanced"><summary>ADVANCED / SOURCE SETTINGS</summary><div class="mask-config"><div class="block-heading">REACTIVE MASK <span>CONTENT-AWARE</span></div>
<label class="input-label">AFFECT REGION <select data-mask-field="${fx.uid}:region">${MASK_REGIONS.map(([id,label])=>`<option value="${id}" ${(fx.mask?.region||'all')===id?'selected':''}>${label}</option>`).join('')}</select></label>
<div class="control compact-control"><div class="control-top"><label>THRESHOLD</label><output data-mask-output="${fx.uid}:threshold">${Number(fx.mask?.threshold??.5).toFixed(2)}</output></div><input type="range" data-mask-field="${fx.uid}:threshold" min="0" max="1" step=".01" value="${fx.mask?.threshold??.5}"></div>
<div class="control compact-control"><div class="control-top"><label>FEATHER</label><output data-mask-output="${fx.uid}:feather">${Number(fx.mask?.feather??.18).toFixed(2)}</output></div><input type="range" data-mask-field="${fx.uid}:feather" min=".005" max=".48" step=".005" value="${fx.mask?.feather??.18}"></div>
<label class="input-label">SECOND REGION<select data-mask-field="${fx.uid}:secondary">${MASK_REGIONS.map(([id,label])=>`<option value="${id}" ${(fx.mask?.secondary||'all')===id?'selected':''}>${label}</option>`).join('')}</select></label><label class="input-label">COMBINE<select data-mask-field="${fx.uid}:combine"><option value="intersect" ${fx.mask?.combine!=='union'?'selected':''}>INTERSECTION</option><option value="union" ${fx.mask?.combine==='union'?'selected':''}>UNION</option></select></label><label class="input-label">HUE / DEGREES<input type="range" min="0" max="360" step="1" data-mask-field="${fx.uid}:hue" value="${fx.mask?.hue||0}"></label><label class="input-label">MASK STRENGTH<input type="range" min="0" max="1" step=".01" data-mask-field="${fx.uid}:strength" value="${fx.mask?.strength??1}"></label><label class="mask-check"><input type="checkbox" data-mask-field="${fx.uid}:preview" ${fx.mask?.preview?'checked':''}> PREVIEW MASK</label><label class="mask-check"><input type="checkbox" data-mask-field="${fx.uid}:invert" ${fx.mask?.invert?'checked':''}> INVERT REGION</label>
<p class="micro-note">The selected effect processes pixels based on the current layer’s luminance, contours or saturation. Masks change as earlier effects change the image.</p></div><label class="input-label">SEED <input type="number" data-fx-extra="${fx.uid}:seed" value="${fx.seed}"></label>${fx.mode===17?['color1','color2','color3'].map((key,i)=>`<label class="input-label">GRADIENT COLOR ${i+1}<input type="color" data-fx-extra="${fx.uid}:${key}" value="${fx[key]||['#17121f','#9d3b60','#ede3d3'][i]}"></label>`).join(''):''}${fx.mode===23?`<label class="input-label">SRT / CAPTION <input type="text" data-fx-extra="${fx.uid}:text" value="${safe(fx.text||'SIGNAL LOST / 2026')}"></label>`:''}<button class="toolbtn full" data-effect-action="random:${fx.uid}">⤨ RANDOMIZE SYSTEM</button></details></div>`).join(''):'<p class="micro-note">Choose a preset on the left to add it to the active layer.</p>'}</div>
 <div class="inspector-block"><div class="block-heading">LAYERS <button class="inline-link" id="image-add-layer">+ SOURCE</button></div><div id="layers-list">${this.layers.slice().reverse().map(l=>`<div class="layer-item ${l.id===this.selected?'active':''}" data-layer="${l.id}" draggable="true"><button data-layer-action="visible:${l.id}" class="icon-button">${l.visible?'●':'○'}</button><button class="layer-name" data-layer-action="select:${l.id}">${safe(l.name)}</button><button data-layer-action="up:${l.id}" class="icon-button" title="Move up">↑</button><button data-layer-action="down:${l.id}" class="icon-button" title="Move down">↓</button><button data-layer-action="duplicate:${l.id}" class="icon-button" title="Duplicate">⧉</button><button data-layer-action="delete:${l.id}" class="icon-button" title="Delete">×</button></div>`).join('')}</div></div>
 <div class="inspector-block"><div class="block-heading">GLOBAL COLOR / OUTPUT <span>POST-FX</span></div>${[['saturation','SATURATION',0,200],['hue','HUE',-180,180],['contrast','CONTRAST',0,200],['brightness','BRIGHTNESS',0,200]].map(([id,label,min,max])=>`<div class="control"><div class="control-top"><label>${label}</label><output data-color-value="${id}">${this.color[id]}${id==='hue'?'°':'%'}</output></div><input type="range" data-color-slider="${id}" min="${min}" max="${max}" value="${this.color[id]}"></div>`).join('')}${[['exposure','EXPOSURE / EV',-200,200,0],['gamma','GAMMA',40,240,100]].map(([key,label,min,max,def])=>`<div class="control"><div class="control-top"><label>${label}</label><output data-finish-value="${key}">${((this.color[key]??def)/100).toFixed(2)}</output></div><input type="range" data-photo-finish="${key}" min="${min}" max="${max}" value="${this.color[key]??def}"></div>`).join('')}<button class="toolbtn full" id="reset-image-color">RESET COLOR</button></div></div>`;}
 asciiControls(fx){const o=asciiSettings(fx),field=(key,label,choices)=>`<label class="input-label">${label}<select data-fx-extra="${fx.uid}:${key}">${choices.map(([value,text])=>`<option value="${value}" ${o[key]===value?'selected':''}>${text}</option>`).join('')}</select></label>`;
 return `<div class="ascii-controls">${field('asciiMode','ASCII / MODE',[['fidelity','FIDELITY / RECONSTRUCT'],['experimental','EXPERIMENTAL / DECONSTRUCT']])}<div class="ascii-comparison">${['fidelity','experimental'].map(mode=>`<button type="button" data-ascii-mode="${fx.uid}:${mode}" title="${mode==='fidelity'?'Reconstruct tones and contours':'Deconstruct with directional text'}"><canvas data-ascii-preview="${fx.uid}:${mode}" width="210" height="140"></canvas><span>${mode.toUpperCase()}</span></button>`).join('')}</div>
 <details open><summary>CHARACTERS / DETAIL / COLOR</summary>
 ${field('asciiSet','CHARACTER SET',[['tonal','TONAL'],['technical','TECHNICAL'],['cyrillic','КИРИЛЛИЦА']])}
 ${field('asciiFont','FONT',[['monospace','MONOSPACE'],['serif','SERIF'],['sans','SANS']])}
 ${field('asciiColor','COLOR MODE',[['original','ORIGINAL COLOR'],['mono','MONOCHROME'],['duotone','WINE / PAPER']])}
 ${field('asciiRegion','BLEND',[['full','FULL REPLACEMENT'],['shadows','SHADOWS ONLY'],['highlights','HIGHLIGHTS ONLY'],['edges','EDGES ONLY'],['hybrid','HYBRID']])}
 ${[['asciiDensity','DENSITY',.5,2],['asciiDetail','DETAIL PRESERVATION',0,1],['asciiEdges','EDGE EMPHASIS',0,1]].map(([key,label,min,max])=>`<label class="input-label">${label}<input type="number" data-fx-extra="${fx.uid}:${key}" min="${min}" max="${max}" step=".05" value="${o[key]}"></label>`).join('')}
 <label class="input-label">CUSTOM TEXT<input type="text" maxlength="160" data-fx-extra="${fx.uid}:asciiText" value="${safe(o.asciiText)}"></label><p class="micro-note">Fidelity reconstructs measured glyph coverage. Experimental follows image contours with mixed character sizes. Reactive Mask below combines with either mode.</p></details></div>`;
 }
 asciiPreviews(source,fx){const elements=$$(`[data-ascii-preview^="${fx.uid}:"]`,this.root);if(!elements.length)return;const c=document.createElement('canvas'),scale=Math.min(1,260/Math.max(source.width,source.height));c.width=source.width;c.height=source.height;c.getContext('2d').putImageData(source,0,0);const small=document.createElement('canvas');small.width=Math.max(1,Math.round(source.width*scale));small.height=Math.max(1,Math.round(source.height*scale));const g=small.getContext('2d');g.drawImage(c,0,0,small.width,small.height);const input=g.getImageData(0,0,small.width,small.height);for(const canvas of elements){canvas.width=small.width;canvas.height=small.height;canvas.getContext('2d').putImageData(renderAscii(input,{...fx,asciiMode:canvas.dataset.asciiPreview.split(':')[1]}),0,0);}}
 bind(){const q=s=>$(s,this.root),all=s=>$$(s,this.root);
 q('#image-load').onclick=()=>this.pickImage();q('#image-bridge').onclick=()=>this.makeReactive();q('#image-compose').onclick=()=>this.makeReactive('generative');q('#image-empty-load')?.addEventListener('click',()=>this.pickImage());q('#image-add-layer')?.addEventListener('click',()=>this.pickImage());
 all('[data-filter]').forEach(b=>b.onclick=()=>{this.category=b.dataset.filter;this.render()});
 q('#image-ascii').onclick=async()=>{if(!this.selectedLayer()){const [file]=await filePicker('image/*');if(!file)return;await this.loadFile(file);}this.addEffect('fx15');};
 q('#preset-search').oninput=e=>{this.search=e.target.value;all('[data-preset]').forEach(el=>{const p=imagePresets.find(x=>x.id===el.dataset.preset);el.hidden=!((p.name+' '+p.category).toLowerCase().includes(this.search.toLowerCase()));});};
 all('[data-preset]').forEach(b=>b.onclick=()=>this.addEffect(b.dataset.preset));
 q('#image-quality').onchange=e=>{this.quality=e.target.value;this.renderCanvas();this.update()};
 q('#zoom-in').onclick=()=>this.zoomSet(this.zoom*1.25);q('#zoom-out').onclick=()=>this.zoomSet(this.zoom/1.25);q('#zoom-fit').onclick=()=>this.zoomSet(1);
 all('[data-fx-range],[data-layer-value],[data-color-slider]').forEach(el=>{el.onpointerdown=()=>this.snapshot();el.onkeydown=e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))this.snapshot()}});
 all('[data-fx-range]').forEach(el=>el.oninput=e=>{const [id,key]=el.dataset.fxRange.split(':'),fx=this.selectedLayer()?.effects.find(x=>x.uid===id);if(!fx)return;fx[key]=Number(el.value);q(`[data-fx-value="${id}:${key}"]`).textContent=fx[key].toFixed(key==='scale'?0:2);this.queueRender();this.update()});
 all('[data-mask-field]').forEach(el=>{const change=()=>{const [id,field]=el.dataset.maskField.split(':'),fx=this.selectedLayer()?.effects.find(x=>x.uid===id);if(!fx)return;fx.mask={...DEFAULT_MASK,...fx.mask};fx.mask[field]=el.type==='checkbox'?el.checked:el.tagName==='SELECT'?el.value:Number(el.value);const out=q(`[data-mask-output="${id}:${field}"]`);if(out)out.textContent=Number(el.value).toFixed(2);this.queueRender();this.update()};el.addEventListener('pointerdown',()=>this.snapshot(),{once:true});el.addEventListener('change',()=>{this.snapshot();change()});if(el.type==='range')el.addEventListener('input',change);});
 all('[data-fx-extra]').forEach(el=>el.onchange=e=>{const [id,key]=el.dataset.fxExtra.split(':'),fx=this.selectedLayer()?.effects.find(x=>x.uid===id);if(!fx)return;this.snapshot();fx[key]=el.type==='number'?Number(el.value):el.value;if(key==='asciiMode')this.render();else this.queueRender();this.update()});
 all('[data-ascii-mode]').forEach(el=>el.onclick=()=>{const [id,mode]=el.dataset.asciiMode.split(':'),fx=this.selectedLayer()?.effects.find(x=>x.uid===id);if(!fx)return;this.snapshot();fx.asciiMode=mode;this.render();this.update()});
 all('[data-effect-action]').forEach(b=>b.onclick=()=>this.effectAction(b.dataset.effectAction));
 all('[data-layer-action]').forEach(b=>b.onclick=()=>this.layerAction(b.dataset.layerAction));
 all('[data-layer-value]').forEach(el=>{el.oninput=e=>{const l=this.selectedLayer();if(!l)return;l[el.dataset.layerValue]=el.type==='range'?Number(el.value):el.value;if(el.type==='range')q('#layer-opacity-value').textContent=Math.round(l.opacity*100)+'%';this.queueRender();this.update()}});
 all('[data-color-slider]').forEach(el=>el.oninput=e=>{this.color[el.dataset.colorSlider]=Number(el.value);q(`[data-color-value="${el.dataset.colorSlider}"]`).textContent=el.value+(el.dataset.colorSlider==='hue'?'°':'%');this.queueRender();this.update()});
 all('[data-photo-finish]').forEach(el=>{el.onpointerdown=()=>this.snapshot();el.oninput=()=>{this.color[el.dataset.photoFinish]=Number(el.value);q(`[data-finish-value="${el.dataset.photoFinish}"]`).textContent=(Number(el.value)/100).toFixed(2);this.queueRender();this.update()}});
 q('#reset-image-color').onclick=()=>{this.snapshot();this.color={...colorDefaults};this.render();this.update()};
 const drop=q('#image-drop');drop.ondragover=e=>{e.preventDefault();drop.classList.add('dragover')};drop.ondragleave=()=>drop.classList.remove('dragover');drop.ondrop=e=>{e.preventDefault();drop.classList.remove('dragover');const files=[...e.dataTransfer.files];files.filter(f=>f.type.startsWith('image/')).forEach(f=>this.loadFile(f,true));};
 let dragged=null;all('.effect-system').forEach(el=>{el.ondragstart=e=>{dragged=el.dataset.effect};el.ondragover=e=>e.preventDefault();el.ondrop=e=>{e.preventDefault();const target=el.dataset.effect;if(!dragged||dragged===target)return;this.snapshot();const l=this.selectedLayer(),a=l.effects.findIndex(f=>f.uid===dragged),b=l.effects.findIndex(f=>f.uid===target);if(a!==-1&&b!==-1){const [item]=l.effects.splice(a,1);l.effects.splice(b,0,item);this.render();this.update()}}});
 let sourceDrag=null;all('.layer-item').forEach(el=>{el.ondragstart=()=>sourceDrag=el.dataset.layer;el.ondragover=e=>e.preventDefault();el.ondrop=e=>{e.preventDefault();if(!sourceDrag||sourceDrag===el.dataset.layer)return;this.snapshot();const a=this.layers.findIndex(l=>l.id===sourceDrag),b=this.layers.findIndex(l=>l.id===el.dataset.layer);if(a!==-1&&b!==-1){const [item]=this.layers.splice(a,1);this.layers.splice(b,0,item);this.render();this.update()}}});
 }
 zoomSet(v){this.zoom=clamp(v,.3,3);const holder=$('.image-canvas-holder',this.root);if(holder)holder.style.transform=`scale(${this.zoom})`;$('#zoom-label',this.root).textContent=Math.round(this.zoom*100)+'%';}
 async pickImage(){const files=await filePicker('image/png,image/jpeg,image/webp,image/gif,image/avif',true);for(const f of files)await this.loadFile(f,true);}
 async loadFile(file,asLayer=true){if(!file||!file.type.startsWith('image/'))return toast('Choose a valid image file','error');try{const bitmap=await createImageBitmap(file);this.snapshot();let id=uid();const requested=this.relink.find(x=>x.name===file.name&&!this.sources.has(x.id));if(requested)id=requested.id;
 this.sources.set(id,{bitmap,name:file.name,width:bitmap.width,height:bitmap.height});this.width=this.width||bitmap.width;this.height=this.height||bitmap.height;
 if(requested){for(const l of this.layers)if(l.sourceId===requested.id)l.sourceName=file.name;this.relink=this.relink.filter(x=>x!==requested)}
 else {const layer={id:uid(),sourceId:id,sourceName:file.name,name:file.name.replace(/\.[^.]+$/,'').slice(0,35),visible:true,opacity:1,blend:'source-over',effects:[]};this.layers.push(layer);this.selected=layer.id;}
 this.render();this.update();toast(requested?'SOURCE RELINKED':'IMAGE LOADED / '+bitmap.width+' × '+bitmap.height);}catch(e){toast('Image decode failed: '+e.message,'error')}}
 async makeReactive(destination='audio'){if(!this.source){toast('LOAD A PHOTO BEFORE MAKING IT REACTIVE','error');return;}if(!this.onBridge)return;const canvas=document.createElement('canvas');try{this.renderTo(canvas,Math.min(1600,this.previewMaxSide()),true);const blob=await blobFromCanvas(canvas,'image/png');const file=new File([blob],(this.selectedLayer()?.name||'sekret')+'-reactive.png',{type:'image/png'});await this.onBridge(file,{name:this.selectedLayer()?.name||'SEKRET COMPOSITION',effects:this.layers.flatMap(l=>l.effects.filter(f=>f.enabled).map(f=>({name:f.name,mask:f.mask||null}))),imageSettings:this.serialize()},destination);toast('IMAGE TRANSFERRED TO '+destination.toUpperCase()+' LAB');}catch(e){toast('LAB BRIDGE FAILED: '+e.message,'error')}}
 previewMaxSide(){return {PERFORMANCE:750,BALANCED:1050,QUALITY:1500}[this.quality]||1050}
 addEffect(presetId){const l=this.selectedLayer();if(!l){toast('LOAD AN IMAGE FIRST','error');return;}const p=imagePresets.find(p=>p.id===presetId);if(!p)return;this.snapshot();l.effects.push(clonePreset(p));this.render();this.update();toast(p.name+' ADDED');}
 effectAction(command){const [action,id]=command.split(':'),l=this.selectedLayer();if(!l)return;const i=l.effects.findIndex(f=>f.uid===id),f=l.effects[i];if(i<0)return;this.snapshot();if(action==='toggle')f.enabled=!f.enabled;else if(action==='delete')l.effects.splice(i,1);else if(action==='up'&&i>0)[l.effects[i-1],l.effects[i]]=[l.effects[i],l.effects[i-1]];else if(action==='down'&&i<l.effects.length-1)[l.effects[i+1],l.effects[i]]=[l.effects[i],l.effects[i+1]];else if(action==='random'){f.seed=Math.floor(Math.random()*100000);f.amount=.5+Math.random()*.5;f.scale=Math.floor(2+Math.random()*12);f.distortion=Math.random();f.contrast=.75+Math.random()*1.65;}this.render();this.update()}
 layerAction(command){const [action,id]=command.split(':'),idx=this.layers.findIndex(l=>l.id===id);if(idx===-1)return;if(action==='select'){this.selected=id;this.render();return;}this.snapshot();const l=this.layers[idx];if(action==='visible')l.visible=!l.visible;else if(action==='delete'){this.layers.splice(idx,1);this.selected=this.layers.at(-1)?.id}else if(action==='duplicate'){const copy=structuredClone(l);copy.id=uid();copy.name+=' COPY';copy.effects.forEach(e=>e.uid=uid());this.layers.splice(idx+1,0,copy);this.selected=copy.id}else if(action==='up'&&idx<this.layers.length-1)[this.layers[idx],this.layers[idx+1]]=[this.layers[idx+1],this.layers[idx]];else if(action==='down'&&idx>0)[this.layers[idx],this.layers[idx-1]]=[this.layers[idx-1],this.layers[idx]];this.render();this.update()}
 queueRender(){clearTimeout(this._renderTimer);this._renderTimer=setTimeout(()=>this.renderCanvas(),70)}
 renderCanvas(){const c=$('#image-canvas',this.root);if(!c)return;if(!this.source){const g=c.getContext('2d');g.fillStyle='#0b0b0e';g.fillRect(0,0,c.width,c.height);g.strokeStyle='#202026';for(let x=0;x<c.width;x+=30){g.beginPath();g.moveTo(x,0);g.lineTo(x,c.height);g.stroke()}for(let y=0;y<c.height;y+=30){g.beginPath();g.moveTo(0,y);g.lineTo(c.width,y);g.stroke()}return;}
 $('#render-status',this.root).textContent='PROCESSING...';requestAnimationFrame(()=>{try{this.renderTo(c,this.previewMaxSide());$('#render-status',this.root).textContent='RENDERED / '+c.width+'×'+c.height;}catch(e){console.error(e);toast('Image render error: '+e.message,'error');$('#render-status',this.root).textContent='ERROR'}})}
 renderTo(target,maxSide,exporting=false){const width=this.width||this.source.width,height=this.height||this.source.height;const ratio=Math.min(1,maxSide/Math.max(width,height));const w=Math.max(1,Math.round(width*ratio)),h=Math.max(1,Math.round(height*ratio));target.width=w;target.height=h;const ctx=target.getContext('2d',{alpha:true,willReadFrequently:true});ctx.clearRect(0,0,w,h);
 for(const layer of this.layers){if(!layer.visible||layer.opacity<=0)continue;const src=this.sources.get(layer.sourceId)?.bitmap;if(!src)continue;const temp=document.createElement('canvas');temp.width=w;temp.height=h;const tc=temp.getContext('2d',{willReadFrequently:true});let entry=this.renderCache.get(layer.id);const cacheable=w*h<=1600000;
 if(!entry||entry.source!==src||entry.width!==w||entry.height!==h){tc.drawImage(src,0,0,w,h);entry={source:src,width:w,height:h,input:tc.getImageData(0,0,w,h),stages:[]};if(cacheable)this.renderCache.set(layer.id,entry);}
 let image=entry.input,stage=0;
 for(const effect of layer.effects)if(effect.enabled){const effective=exporting&&effect.mask?.preview?{...effect,mask:{...effect.mask,preview:false}}:effect,key=JSON.stringify(effective),prior=entry.stages[stage];if(effect.mode===15&&!exporting)this.asciiPreviews(image,effect);
 if(prior&&prior.input===image&&prior.key===key)image=prior.output;else{const input=image;image=processEffect(image,effective);if(cacheable)entry.stages[stage]={input,key,output:image};}stage++;}entry.stages.length=stage;
 for(const id of this.renderCache.keys())if(!this.layers.some(l=>l.id===id))this.renderCache.delete(id);
 let bytes=0;for(const [id,cache] of [...this.renderCache].reverse()){bytes+=cache.width*cache.height*4*(1+cache.stages.length);if(bytes>64*1024*1024)this.renderCache.delete(id);}
 tc.putImageData(image,0,0);ctx.globalAlpha=layer.opacity;ctx.globalCompositeOperation=layer.blend;ctx.drawImage(temp,0,0);
 }
 ctx.globalAlpha=1;ctx.globalCompositeOperation='source-over';const {saturation,hue,contrast,brightness}=this.color;
 if(saturation!==100||hue!==0||contrast!==100||brightness!==100){const temp=document.createElement('canvas');temp.width=w;temp.height=h;temp.getContext('2d').drawImage(target,0,0);ctx.clearRect(0,0,w,h);ctx.filter=`saturate(${saturation}%) hue-rotate(${hue}deg) contrast(${contrast}%) brightness(${brightness}%)`;ctx.drawImage(temp,0,0);ctx.filter='none';}
 if((this.color.exposure||0)!==0||(this.color.gamma??100)!==100){const pixels=ctx.getImageData(0,0,w,h),d=pixels.data,gain=2**((this.color.exposure||0)/100),gamma=100/(this.color.gamma||100);for(let i=0;i<d.length;i+=4)for(let k=0;k<3;k++)d[i+k]=255*Math.pow(clamp(d[i+k]/255*gain,0,1),gamma);ctx.putImageData(pixels,0,0);}
 }
 demoSource(){if(this._demo)return this._demo;const c=document.createElement('canvas');c.width=170;c.height=130;const g=c.getContext('2d');const grd=g.createLinearGradient(0,0,170,130);grd.addColorStop(0,'#ece5dc');grd.addColorStop(.48,'#86848d');grd.addColorStop(1,'#16121b');g.fillStyle=grd;g.fillRect(0,0,170,130);g.fillStyle='#15151c';g.fillRect(14,12,27,105);g.fillStyle='#ece8e6';g.font='bold 96px Arial';g.fillText('S',42,97);g.strokeStyle='#e8e8e8';g.lineWidth=3;g.beginPath();g.arc(115,65,50,0,6.28);g.stroke();this._demo=c;return c}
 async buildThumbnails(){const items=$$('[data-thumb]',this.root);const token=++this._thumbToken;const source=this.source?.bitmap||this.demoSource();if(this._thumbSource!==source){this.thumbCache.clear();this._thumbSource=source;}const base=document.createElement('canvas'),s=Math.min(1,145/Math.max(source.width,source.height));base.width=Math.max(1,Math.round(source.width*s));base.height=Math.max(1,Math.round(source.height*s));base.getContext('2d',{willReadFrequently:true}).drawImage(source,0,0,base.width,base.height);const data=base.getContext('2d',{willReadFrequently:true}).getImageData(0,0,base.width,base.height);let index=0;
 const next=()=>{if(token!==this._thumbToken||!this.root.isConnected)return;const el=items[index++];if(!el)return;const fx=imagePresets.find(p=>p.id===el.dataset.thumb);try{const key=(this.source?.id||this.selectedLayer()?.sourceId||'demo')+':'+fx.id;let processed=this.thumbCache.get(key);if(!processed){processed=processEffect(data,fx);this.thumbCache.set(key,processed);if(this.thumbCache.size>150)this.thumbCache.delete(this.thumbCache.keys().next().value);}const canvas=document.createElement('canvas');canvas.width=base.width;canvas.height=base.height;canvas.getContext('2d').putImageData(processed,0,0);canvas.className='preset-image';canvas.setAttribute('aria-hidden','true');el.prepend(canvas);const original=document.createElement('canvas');original.width=base.width;original.height=base.height;original.getContext('2d').drawImage(base,0,0);original.className='preset-original';el.prepend(original);}catch(e){console.warn('Thumbnail failed:',fx?.name,e)}setTimeout(next,8);};setTimeout(next,4)
 }
 async export(){if(!this.source){toast('Load an image to export','error');return;}const modal=document.createElement('div');modal.className='modal-backdrop';modal.innerHTML=`<div class="dialog"><div class="dialog-title">EXPORT IMAGE <button id="close-export" class="icon-button">×</button></div><p>Match Preview preserves the exact visual treatment; HD Reprocess uses native pixels but fine-grained procedural details may change. Choose based on your output.</p><label class="input-label">RENDER MODE <select id="export-mode"><option value="match">MATCH PREVIEW / WYSIWYG</option><option value="hd">HD REPROCESS / SOURCE PIXELS</option></select></label><label class="input-label">WIDTH (PX) <input type="number" id="export-width" min="64" max="8000" value="${this.width}"></label><label class="input-label">FORMAT <select id="export-format"><option value="image/png">PNG / ALPHA</option><option value="image/jpeg">JPEG</option><option value="image/webp">WEBP</option></select></label><label class="input-label">QUALITY / JPG-WEBP <input id="export-quality" type="range" min=".5" max="1" step=".01" value=".92"></label><button id="confirm-export" class="toolbtn primary full">RENDER & SAVE ↗</button><div id="export-note" class="micro-note"></div></div>`;document.body.append(modal);modal.onclick=e=>{if(e.target===modal)modal.remove()};$('#close-export',modal).onclick=()=>modal.remove();$('#confirm-export',modal).onclick=async()=>{const width=clamp(Number($('#export-width',modal).value),64,8000),height=Math.round(width*this.height/this.width);if(width*height>28_000_000){toast('Output exceeds safe pixel budget (28MP)','error');return;}const canvas=document.createElement('canvas');try{$('#export-note',modal).textContent='RENDERING ORIGINAL SOURCE...';await new Promise(r=>setTimeout(r,30));const mode=$('#export-mode',modal).value;this.renderTo(canvas,mode==='match'?this.previewMaxSide():Math.max(width,height),true);if(canvas.width!==width||canvas.height!==height){const c=document.createElement('canvas');c.width=width;c.height=height;const cg=c.getContext('2d');cg.imageSmoothingEnabled=true;cg.imageSmoothingQuality='high';cg.drawImage(canvas,0,0,width,height);canvas.width=c.width;canvas.height=c.height;canvas.getContext('2d').drawImage(c,0,0)}const type=$('#export-format',modal).value,quality=Number($('#export-quality',modal).value);if(type==='image/jpeg'){const flat=document.createElement('canvas');flat.width=canvas.width;flat.height=canvas.height;const g=flat.getContext('2d');g.fillStyle='#ffffff';g.fillRect(0,0,flat.width,flat.height);g.drawImage(canvas,0,0);const blob=await blobFromCanvas(flat,type,quality);download(blob,slug(this.selectedLayer()?.name||'sekret')+'.jpg')}else{const blob=await blobFromCanvas(canvas,type,quality);download(blob,slug(this.selectedLayer()?.name||'sekret')+(type==='image/png'?'.png':'.webp'))}modal.remove();toast('EXPORT COMPLETE');}catch(e){$('#export-note',modal).textContent='Export failed: '+e.message;toast('EXPORT FAILED','error')}};
 }
 dispose(){this._thumbToken++;clearTimeout(this._renderTimer);for(const source of this.sources.values())source.bitmap?.close?.();this.sources.clear();this.renderCache.clear();this.root.innerHTML='';}
}
